function upgma(labels, D){
  var n=labels.length;
  var clusters=labels.slice();
  var sizes=labels.map(function(){return 1;});
  var d=D.map(function(r){return r.slice();});
  var height=labels.map(function(){return 0;});
  while(clusters.length>1){
    var mi=0,mj=1,mn=Infinity;
    for(var i=0;i<clusters.length;i++) for(var j=i+1;j<clusters.length;j++){ if(d[i][j]<mn){mn=d[i][j];mi=i;mj=j;} }
    var h=mn/2;
    var ni=sizes[mi], nj=sizes[mj], ns=ni+nj;
    var newRow=[]; for(var k=0;k<clusters.length;k++){ if(k===mi||k===mj) continue; newRow.push((d[mi][k]*ni+d[mj][k]*nj)/ns); }
    var idx=[]; for(var a=0;a<clusters.length;a++){ if(a!==mi&&a!==mj) idx.push(a); }
    var nd=[]; for(var a=0;a<idx.length;a++){ var row=[]; for(var b=0;b<idx.length;b++){ row.push(d[idx[a]][idx[b]]); } row.push(newRow[a]); nd.push(row); }
    var lastRow=newRow.slice(); lastRow.push(0); nd.push(lastRow);
    var nc=[], nsz=[], nh=[]; for(var a=0;a<idx.length;a++){ nc.push(clusters[idx[a]]); nsz.push(sizes[idx[a]]); nh.push(height[idx[a]]); }
    nc.push(clusters[mi]+"/"+clusters[mj]); nsz.push(ns); nh.push(h);
    clusters=nc; sizes=nsz; height=nh; d=nd;
  }
  return {root:clusters[0], height:height[0]};
}
var EXPORTS={upgma:upgma};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PhylogeneticForgePure = EXPORTS; }
